const DISPATCH_ASSET_VERSION = document.querySelector('meta[name="dispatch-asset-version"]')?.content || "dev";

// ═══════════════════════════════════════════════════════════
// PRIVACY-SAFE PROJECT ANALYTICS
// Replit injects the Umami tracker on published website HTML. Keep all
// analytics optional and send only bounded, non-identifying dimensions.
// ═══════════════════════════════════════════════════════════
const _ANALYTICS_CONTEXT_KEY = "dispatch_analytics_context_v1";

function _analyticsValue(value, fallback = "unknown") {
  const cleaned = String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .slice(0, 48);
  return cleaned || fallback;
}

function _analyticsPage(pathname = location.pathname) {
  const page = pathname.replace(/^\/+|\/+$/g, "");
  if (!page) return "home";
  if (page === "brief") return "brief";
  if (page === "research") return "research";
  if (page === "login" || page === "subscribe") return "account";
  return _analyticsValue(page.split("/")[0], "other");
}

function _analyticsDevice() {
  if (window.matchMedia?.("(max-width: 767px)").matches) return "mobile";
  if (window.matchMedia?.("(max-width: 1023px)").matches) return "tablet";
  return "desktop";
}

function _analyticsContext() {
  let context;
  try {
    context = JSON.parse(sessionStorage.getItem(_ANALYTICS_CONTEXT_KEY) || "null");
  } catch {}
  if (!context || typeof context !== "object") {
    const params = new URLSearchParams(location.search);
    context = {
      source: _analyticsValue(params.get("utm_source"), "direct"),
      campaign: _analyticsValue(params.get("utm_campaign"), "none"),
      entry_page: _analyticsPage(),
      device: _analyticsDevice(),
    };
    try { sessionStorage.setItem(_ANALYTICS_CONTEXT_KEY, JSON.stringify(context)); } catch {}
  }
  return context;
}

function _trackDispatchEvent(name, properties = {}) {
  if (typeof window === "undefined") return;
  try {
    if (typeof window.umami?.track !== "function") return false;
    window.umami?.track(name, {
      ..._analyticsContext(),
      page: _analyticsPage(),
      ...properties,
    });
    return true;
  } catch {
    // Analytics must never interrupt the product experience.
    return false;
  }
}

function _trackDispatchEventOnce(key, name, properties = {}) {
  try {
    const storageKey = `dispatch_analytics_${key}`;
    if (sessionStorage.getItem(storageKey)) return;
  } catch {}
  if (_trackDispatchEvent(name, properties)) {
    try { sessionStorage.setItem(`dispatch_analytics_${key}`, "1"); } catch {}
  }
}

function _consumeSignupCompletion() {
  const created = document.cookie.split(";").some(cookie => cookie.trim().startsWith("dispatch_account_created="));
  if (!created) return;
  document.cookie = "dispatch_account_created=; Path=/; SameSite=Lax; Max-Age=0";
  _trackDispatchEvent("signup_completed", { account: "created", location: "subscribe_form" });
}

function _handleAnalyticsLinkClick(event) {
  const link = event.target.closest?.("a[href]");
  if (!link) return;
  let path = "";
  try { path = new URL(link.href, location.href).pathname; } catch {}
  if (path === "/__auth/subscribe") {
    _trackDispatchEvent("signup_started", { location: "subscribe_link" });
  }
}

document.addEventListener("click", _handleAnalyticsLinkClick, true);

// API CONFIG — Finnhub proxied via /api/finnhub (key never exposed to browser)
// ═══════════════════════════════════════════════════════════

const _CHART_GATE_MAX = 6;
const _CHART_GATE_SPACING_MS = 90;
let _chartGateActive = 0;
let _chartGateLastStart = 0;
const _chartGateQueue = [];

function _chartGateStart(run) {
  _chartGateActive++;
  const wait = Math.max(0, _chartGateLastStart + _CHART_GATE_SPACING_MS - Date.now());
  _chartGateLastStart = Date.now() + wait;
  if (wait) setTimeout(run, wait); else run();
}

function _chartGateRelease() {
  _chartGateActive--;
  const next = _chartGateQueue.shift();
  if (next) _chartGateStart(next);
}

/** fetch() for /api/yahoo-chart — at most _CHART_GATE_MAX in flight, paced. */
function chartFetch(url, opts) {
  return new Promise((resolve, reject) => {
    const run = () => {
      let settled = false;
      const done = () => { if (!settled) { settled = true; _chartGateRelease(); } };
      // Release on settle either way, so a rejection cannot wedge the queue.
      fetch(url, opts).then(
        (r) => { done(); resolve(r); },
        (e) => { done(); reject(e); }
      );
    };
    if (_chartGateActive < _CHART_GATE_MAX) _chartGateStart(run);
    else _chartGateQueue.push(run);
  });
}

