    intel.keyDisagreements.forEach(d => { h += `<div style="font-size:11px;color:var(--t2);padding:4px 0;line-height:1.5;display:flex;gap:6px"><span style="color:var(--pu);flex-shrink:0">⚡</span>${d}</div>`; });
    h += `</div>`;
