function _savePriceCache(){
  try{
    const payload={
      ts:Date.now(),
      P:Object.fromEntries([...liveSymbols].map(tk=>[tk,P[tk]])),
      BASE:Object.fromEntries([...liveSymbols].map(tk=>[tk,BASE[tk]])),
      live:[...liveSymbols],
      quoteTs:Object.fromEntries([...liveSymbols].map(tk=>[tk,liveQuoteTs[tk]||Date.now()])),
      quoteSrc:Object.fromEntries([...liveSymbols].map(tk=>[tk,liveQuoteSrc[tk]||"session-cache"])),
      quoteName:Object.fromEntries([...liveSymbols].map(tk=>[tk,liveQuoteName[tk]||""])),
      quoteCached:Object.fromEntries([...liveSymbols].map(tk=>[tk,!!liveQuoteCached[tk]])),
       quoteChange:Object.fromEntries([...liveSymbols].map(tk=>[tk,liveQuoteChangeAvailable[tk] !== false])),
      quoteProxy:Object.fromEntries([...liveSymbols].map(tk=>[tk,!!liveQuoteProxy[tk]])),
      quoteClosed:Object.fromEntries([...liveSymbols].map(tk=>[tk,!!liveQuoteMarketClosed[tk]])),
    };
    const _rt18Json=JSON.stringify(payload);
    sessionStorage.setItem(PRICE_CACHE_KEY,_rt18Json);
    try{ if(Date.now()-(window._rt18LsSaved||0)>30000){ localStorage.setItem("td_price_cache_ls",_rt18Json); window._rt18LsSaved=Date.now(); } }catch(e){}
  }catch(e){}
}

function _loadPriceCache(){
  try{
    let _rt18Ls=false;
    let raw=sessionStorage.getItem(PRICE_CACHE_KEY)||sessionStorage.getItem("td_price_cache_v1");
    if(!raw){try{raw=localStorage.getItem("td_price_cache_ls");_rt18Ls=!!raw;}catch(e){}}
    if(!raw)return false;
    const data=JSON.parse(raw);
    if(!data?.ts||Date.now()-data.ts>(_rt18Ls?12*3600*1000:PRICE_CACHE_MAX_AGE))return false;
    if(!Array.isArray(data.live)||!data.live.length)return false;
    let n=0;
    data.live.forEach(tk=>{
      const row=data.P?.[tk];
      if(!row||typeof row.p!=="number"||!isFinite(row.p)||row.p<=0)return;
      P[tk]={p:row.p,c:typeof row.c==="number"?row.c:0};
      if(data.BASE?.[tk]?.p>0)BASE[tk]=data.BASE[tk];
      else BASE[tk]={p:row.p,c:0};
      liveSymbols.add(tk);
      // Restored session quotes are cached — never pretend they just hit the wire
      liveQuoteTs[tk]=data.quoteTs?.[tk]||data.ts;
      liveQuoteSrc[tk]=data.quoteSrc?.[tk]||"session-cache";
      liveQuoteName[tk]=data.quoteName?.[tk]||"";
      liveQuoteCached[tk]=true;
      liveQuoteChangeAvailable[tk]=data.quoteChange?.[tk] !== false
        && typeof data.P?.[tk]?.c === "number"
        && isFinite(data.P[tk].c);
      liveQuoteProxy[tk]=!!data.quoteProxy?.[tk];
      liveQuoteMarketClosed[tk]=!!data.quoteClosed?.[tk];
      n++;
    });
    if(!n)return false;
    priceLastFetch=new Date(data.ts);
    return true;
  }catch(e){return false;}
}

function _safeNewsUrl(value){
  if(typeof value!=="string"||!value.trim())return "";
  try{
    const url=new URL(value.trim());
    if(url.protocol!=="http:"&&url.protocol!=="https:")return "";
    // News links should never carry credentials in a browser navigation.
    if(url.username||url.password)return "";
    return url.href;
  }catch(e){return "";}
}

function _newsLink(n){
  const safe=_safeNewsUrl(n?.link);
  if(safe)return safe;
  const q=String(n?.x||"").replace(/\.\.\.$/,"").trim();
  return q?`https://www.google.com/search?q=${encodeURIComponent(q)}`:"";
}

function _applyLiveQuote(tk, q, source) {
  if (!tk || !q || typeof q.p !== "number" || !isFinite(q.p) || q.p <= 0) return false;
  if (typeof _rtGuard === "function" && _rtGuard(tk, q, source)) return true; // rt9: fresher stream tick wins
  const hasProviderTs = q.ts != null || q.fetchedAt != null;
  const providerTs = Number(q.ts ?? q.fetchedAt);
  const sourceFetchedAt = providerTs > 0 && providerTs < 10_000_000_000 ? providerTs * 1000 : providerTs;
  if (hasProviderTs && (
    !Number.isFinite(sourceFetchedAt)
    || sourceFetchedAt <= 0
    || sourceFetchedAt > Date.now() + 60_000
  )) return false;
  const hasChange = typeof q.c === "number" && isFinite(q.c);
  const hasPrevious = typeof q.prev === "number" && isFinite(q.prev) && q.prev > 0;
  const c = hasChange ? q.c : 0;
  const prev = hasPrevious ? q.prev : (hasChange ? q.p / (1 + c / 100) : q.p);
  P[tk] = { p: q.p, c: +c.toFixed(2) };
  BASE[tk] = { p: prev, c: 0 };
  if (!HIST[tk]) HIST[tk] = [];
  HIST[tk].push(q.p);
  if (HIST[tk].length > 120) HIST[tk].shift();
  liveSymbols.add(tk);
  // Provider timestamps are in seconds for Yahoo/Twelve Data. Prefer them
  // over browser receipt time so delayed quotes cannot look freshly live.
  liveQuoteTs[tk] = Number.isFinite(sourceFetchedAt) && sourceFetchedAt > 0
    ? sourceFetchedAt
    : Date.now();
  liveQuoteSrc[tk] = q.source || source || "yahoo";
  liveQuoteName[tk] = q.name || "";
  liveQuoteCached[tk] = !!q.cached;
  liveQuoteMarketClosed[tk] = _isContinuousTapeTicker(tk) ? false : !!q.marketClosed;
  liveQuoteSession[tk] = _isContinuousTapeTicker(tk) ? null : (q.session || null);
  if (typeof liveQuoteChangeAvailable !== "undefined") {
    liveQuoteChangeAvailable[tk] = hasChange || hasPrevious;
  }
  liveQuoteProxy[tk] = !!q.proxy
    || liveQuoteSrc[tk].startsWith("gold-api-spot-proxy")
    || liveQuoteSrc[tk] === "frankfurter-ecb"
    || liveQuoteSrc[tk] === "open-exchange-rate-api";
  return true;
}
