function bd(t,c){const bg=c==="var(--gn)"?"var(--gnG)":c==="var(--rd)"?"var(--rdG)":c==="var(--gd)"?"var(--gdG)":c==="var(--pu)"?"var(--puG)":"var(--blG)";
  return `<span class="bd" style="background:${bg};color:${c}">${t}</span>`;}
function _renderAiRetryState(onRetry, surface = "research") {
  const label = String(surface || "research");
  const copy = label === "Dispatch Brief"
    ? "The AI upgrade is unavailable. The free tape brief below is still active."
    : label === "site intelligence"
      ? "The AI update is unavailable. The local PULSE context remains available."
      : `The ${label} response could not be published.`;
  return `<div class="ai-retry-state" role="status">
    <div><strong>${label === "site intelligence" ? "AI update unavailable" : "AI upgrade unavailable"}</strong><span>${copy} Try again to request the same research.</span></div>
    <button type="button" class="ai-retry-btn" onclick="${onRetry}">Try again</button>
  </div>`;
}
function scC(v){return v>=75?"var(--gn)":v>=50?"var(--bl)":v>=35?"var(--gd)":"var(--rd)";}
// Format a ticker. Seed prices are NEVER returned as market prices.
// status: live | delayed | stale | cached | unavailable
function fp(tk){
  tk=(typeof resolveInternalTicker==="function"&&resolveInternalTicker(tk))||tk;
  const meta=_quoteMeta(tk);
  const d=P[tk];
  const hasPx=liveSymbols.has(tk)&&d&&typeof d.p==="number"&&isFinite(d.p)&&d.p>0;
  if (!hasPx) {
    if (liveSymbols.has(tk)) liveSymbols.delete(tk); // corrupt entry — drop
    return {
      p: "—", c: "—", chg: "—", raw: 0, d: 0,
      status: "unavailable", label: (typeof _rt20Booting === "function" && (_rt20Booting() || !priceLastFetch)) ? "SYNCING" : "NO QUOTE",
      asOf: null, age: "—", src: null, detail: meta.detail||"Awaiting live feed"
    };
  }
  const base=BASE[tk]&&BASE[tk].p>0?BASE[tk]:{p:d.p};
  const chg=d.p-base.p;
  const fx4=d.p<50&&tk!=="TNX"&&typeof TICKER_CATS!=="undefined"&&TICKER_CATS[tk]==="fx";
  const p=(typeof _rtIsCrypto==="function"&&_rtIsCrypto(tk))?_rtCryptoPx(d.p):d.p>=10000?Math.round(d.p).toLocaleString():fx4?d.p.toFixed(4):d.p>=1?d.p.toFixed(2):d.p.toFixed(4);
  const fmtChg = Math.abs(chg)>=1000?Math.round(chg).toLocaleString():chg.toFixed(2);
  const pct = Number(d.c);
  const pctN = isFinite(pct) ? pct : 0;
  // d polarity: +1 up, -1 down, 0 flat — never treat flat as up
  const dir = pctN > 0 ? 1 : pctN < 0 ? -1 : 0;
  return{
    p, ..._rt24XauFp(tk, d.p, { c: pctN.toFixed(2), chg: fmtChg, raw: chg, d: dir }),
    status: meta.status, label: meta.label,
    asOf: meta.asOf, age: meta.asOf ? _fmtAge(meta.asOf) : "—",
    src: meta.src, detail: meta.detail
  };
}
// Neutral dim placeholder for change cells until a live quote arrives —
// a red ↓0.00% wall reads as "site is broken", a quiet — reads as "loading"
function chgDim(){return `<span style="color:var(--t3);opacity:0.55;font-weight:400">—</span>`;}
function ring(sc,sz=40){const r=(sz-4)/2,ci=2*Math.PI*r,of=ci-(sc/100)*ci,c=scC(sc);
  return `<div style="position:relative;width:${sz}px;height:${sz}px;flex-shrink:0"><svg width="${sz}" height="${sz}" style="transform:rotate(-90deg)"><circle cx="${sz/2}" cy="${sz/2}" r="${r}" fill="none" stroke="var(--b3)" stroke-width="3"/><circle cx="${sz/2}" cy="${sz/2}" r="${r}" fill="none" stroke="${c}" stroke-width="3" stroke-dasharray="${ci}" stroke-dashoffset="${of}" stroke-linecap="round"/></svg><span style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-family:var(--mn);font-weight:800;font-size:${sz*0.26}px;color:${c}">${sc}</span></div>`;}
// Sparkline: render only from real data points. If <5 valid points, show a
// muted placeholder rather than fabricating a line.
const _sparkPending=new Set();
async function _ensureSparkline(tk){
  if(_sparkPending.has(tk)||(HIST[tk]||[]).filter(v=>typeof v==="number"&&isFinite(v)&&v>0).length>=5)return;
  _sparkPending.add(tk);
  try{
    // Desk crypto: CoinGecko only — Yahoo UNI-USD/SHIB-USD etc. are junk micros
    const cgId=_cgIdForTicker(tk);
    if(cgId){
      const cgSeries=await fetchCgSpark(cgId,1);
      if(cgSeries&&cgSeries.length>=5){
        HIST[tk]=cgSeries.slice(-60);
        _patchSparkline(tk);
        return;
      }
      // Majors may still fall through to Yahoo if CG 429'd
      if(typeof YAHOO_CRYPTO_OK==="undefined"||!YAHOO_CRYPTO_OK.has(tk))return;
    }
    const yhSym=YAHOO_SYMBOLS[tk];
    if(!yhSym)return;
    const series=await fetchYahooIntraday(yhSym);
    if(series&&series.length>=5){
      HIST[tk]=series.slice(-60);
      _patchSparkline(tk);
    }
  }catch(e){}
  finally{_sparkPending.delete(tk);if(typeof _rtSparkDone==="function")_rtSparkDone(tk);}
}
function _patchSparkline(tk){
  document.querySelectorAll(`[data-spark-tk="${tk}"]`).forEach(el=>{
    const w=parseInt(el.dataset.sparkW||"72",10),h=parseInt(el.dataset.sparkH||"18",10);
    el.innerHTML=spark(tk,w,h,true);
    if(el.querySelector("svg")){el.style.border="none";el.style.opacity="1";el.style.display="block";}
  });
}
function _patchCuratedPrices(){
  document.querySelectorAll("[data-price-card]").forEach(el=>{
    const tk=el.dataset.priceCard;
    if(!tk||!liveSymbols.has(tk))return;
    const d=fp(tk),showDollar=el.dataset.priceDollar==="1";
    const pctOnly=el.dataset.priceChg==="pct";
    const chgN=liveChg(tk);
    const col=chgN==null?"var(--t3)":chgN>0?"var(--gn)":chgN<0?"var(--rd)":"var(--t3)";
    const sign=d.raw>=0?"+":"";
    const priceEl=el.querySelector(".asset-price");
    const chgEl=el.querySelector(".asset-chg");
    if(priceEl)priceEl.textContent=hasSyncedQuote(tk)?(showDollar?"$":"")+d.p:_rt22NoSync();
    if(chgEl){
      chgEl.style.color=col;
       chgEl.textContent=chgN==null?"—":(pctOnly?`${sign}${d.c}%`:`${sign}${d.chg} (${sign}${d.c}%)`);
      chgEl.classList.remove("px-up","px-dn","px-flat");
      chgEl.classList.add(chgN==null||chgN===0?"px-flat":chgN>0?"px-up":"px-dn");
    }
    const liveBadge=el.querySelector(".bd");
    if(liveBadge&&liveBadge.textContent==="N/A")liveBadge.outerHTML=stat(tk);
  });
}
function spark(tk,w=90,h=22,_skipLazy){
  const raw=HIST[tk]||[];
  const d=raw.filter(v=>typeof v==="number"&&isFinite(v)&&v>0);
  if(d.length<5){
    if(typeof _rtSparkGaveUp==="function"&&_rtSparkGaveUp(tk))return _rtSparkHiddenHtml(tk,w,h);
    if(!_skipLazy){if(typeof _rtSparkLazy==="function")_rtSparkLazy(tk);else _ensureSparkline(tk);}
    return `<div data-spark-tk="${tk}" data-spark-w="${w}" data-spark-h="${h}" role="img" aria-label="Chart loading" style="width:${w}px;height:${h}px;display:flex;align-items:center;justify-content:center;font-family:var(--mn);font-size:7.5px;color:var(--t3);letter-spacing:0.08em;border:1px dashed var(--gb);border-radius:4px;opacity:0.55">${typeof _rtSparkPhTxt==="function"?_rtSparkPhTxt(tk):"— loading —"}</div>`;
  }
  const mn=Math.min(...d),mx=Math.max(...d),rng=mx-mn||Math.max(mx*0.001,1e-9);
  const chN=liveChg(tk);
  const col=chN==null?"var(--t3)":chN>0?"var(--gn)":chN<0?"var(--rd)":"var(--t3)";
  const pts=d.map((v,i)=>`${(i/(d.length-1))*w},${h-((v-mn)/rng)*h*0.8-h*0.08}`).join(" ");
  return `<svg role="img" aria-label="${tk} intraday sparkline" width="${w}" height="${h}" style="display:block"><polyline points="${pts}" fill="none" stroke="${col}" stroke-width="1.3"/></svg>`;
}
function _quoteSourceLabel(src) {
  if (!src) return "unknown feed";
  if (src === "coinbase-ws") return "Coinbase stream";
  if (src === "kraken-ws") return "Kraken stream";
  if (src === "yahoo-stream") return "Yahoo stream";
  if (src === "gold-api-spot-proxy-browser") return "gold-api.com spot proxy";
  if (src === "twelve-data") return "Twelve Data";
  if (src === "coingecko") return "CoinGecko";
  if (src === "yahoo" || src === "yahoo-screener") return "Yahoo Finance";
  if (src === "finnhub") return "Finnhub";
  if (src.startsWith("gold-api-spot-proxy")) return "Spot Gold proxy";
  if (src === "frankfurter-ecb" || src === "open-exchange-rate-api") return "Synthetic DXY proxy";
  if (src === "session-cache") return "Browser session cache";
  if (src.endsWith("-last-good")) return "Last-good cache";
  return src;
}
// Compact status pill — LIVE / DELAYED / STALE / CACHED / PROXY / UNAVAILABLE
function stat(tk){
  const d=fp(tk);
  const s=d.status||"unavailable";
  const title=_escAttr(`${d.label||s}${d.asOf?` · as of ${_fmtAsOf(d.asOf)} (${d.age})`:""}${d.detail?` · ${d.detail}`:""}`);
  if(s==="live")return `<span class="bd trust-stat trust-stat-live" title="${title}" style="background:var(--gnG);color:var(--gn);font-size:7.5px">${_escHtml(d.label||"LIVE")}</span>`;
  if(s==="delayed")return `<span class="bd trust-stat trust-stat-delayed" title="${title}" style="background:var(--blG);color:var(--bl);font-size:7.5px">${_escHtml(d.label||"DELAYED")}</span>`;
  if(s==="closed")return `<span class="bd trust-stat trust-stat-cached" title="${title}" style="background:var(--puG);color:var(--pu);font-size:7.5px">CLOSED</span>`;
  if(s==="stale")return `<span class="bd trust-stat trust-stat-stale" title="${title}" style="background:var(--gdG);color:var(--gd);font-size:7.5px">STALE</span>`;
  if(s==="cached")return `<span class="bd trust-stat trust-stat-cached" title="${title}" style="background:var(--puG);color:var(--pu);font-size:7.5px">CACHED</span>`;
  if(s==="proxy")return `<span class="bd trust-stat trust-stat-delayed" title="${title}" style="background:var(--gdG);color:var(--gd);font-size:7.5px">${_escHtml(d.label||"PROXY")}</span>`;
  if(s!=="unavailable"&&d.label&&hasSyncedQuote(tk))return s==="extended"
    ?`<span class="bd trust-stat trust-stat-delayed" title="${title}" style="background:var(--blG);color:var(--bl);font-size:7.5px">${_escHtml(d.label)}</span>`
    :`<span class="bd trust-stat trust-stat-cached" title="${title}" style="background:var(--puG);color:var(--pu);font-size:7.5px">${_escHtml(d.label)}</span>`;
  return `<span class="bd trust-stat trust-stat-na" title="${title}" style="background:var(--b3);color:var(--t3);font-size:7.5px">UNAVAILABLE</span>`;
}
function asOfTag(tk){
  const d=fp(tk);
  if(d.status==="unavailable"||!d.asOf){try{if(_rt20Booting()||!priceLastFetch)return "";}catch(e){}return `<span class="asof-tag asof-na" title="${_escAttr(d.detail||"No quote from the free feeds for this symbol this session")}">no quote</span>`;}
  if(d.status==="closed")return `<span class="asof-tag" title="${_escAttr(d.detail||"")}">${_escHtml(_quoteSourceLabel(d.src))} · CLOSED · last close ${_rt18CloseLbl(_rt20LastClose(tk) || d.asOf)}</span>`;
  return `<span class="asof-tag" title="${_escAttr(d.detail||"")}">${_escHtml(_quoteSourceLabel(d.src))} · as of ${_fmtAsOf(d.asOf)} · ${d.age}</span>`;
}

