// FREEMIUM — AUTH GATE (server-verified via /api/me)
// ═══════════════════════════════════════════════════════════
let _userTier="free";
let _userTierReady=false;
let _userBilling=false;
let _userSignedIn=false;
let _userAdmin=false;
let _editorialContent={};

async function _loadEditorialContent(){
  try{
    const results=await Promise.all(["brief","report","research"].map(type=>fetch(`/api/public/content?type=${type}`,{credentials:"include",signal:AbortSignal.timeout(4000)}).then(res=>res.ok?res.json():[]).catch(()=>[])));
    results.flat().forEach(record=>{
      if(record?.type&&record?.key&&record?.payload) _editorialContent[`${record.type}:${record.key}`]=record;
    });
  }catch(e){}
}

function _enhanceInitialEditorialRoute(){
  if(!_initialEditorialRoute||!_initialEditorialHtml)return;
  // Anonymous editorial pages are already complete server-rendered documents.
  // Do not mount a terminal overlay on top of that public article.
  if (_isVisitor()) {
    _closeDeskOverlays();
    _syncFrontDoorMode();
    return;
  }
  const record=_editorialContent[`${_initialEditorialRoute.type}:${_initialEditorialRoute.key}`];
  const title=record?.payload?.headline||"Dispatch Editorial";
  if(IS_DESKTOP()){
    _showOverlay("researchOv",`Research · ${_escHtml(title)}`,_initialEditorialHtml);
    updateSidebarActive();
    return;
  }
  const main=document.getElementById("main");
  if(main)main.innerHTML=_initialEditorialHtml;
}

async function _initUserTier(){
  // Editorial content does not depend on /api/me: start both at once so the
  // boot veil (and the front-door prices under it) lifts one round-trip sooner.
  const editorialReady=_loadEditorialContent();
  try{
    const res=await fetch("/api/me",{credentials:"include",signal:AbortSignal.timeout(5000)});
    if(res.ok){
      const d=await res.json();
      _userSignedIn=!!d.id;
      _userTier=d.tier==="premium"?"premium":"free";
      _userBilling=!!d.billingPortal;
      _userAdmin=d.isAdmin===true;
      window._tdMeEmail=typeof d.email==="string"?d.email:"";
    }
  }catch(e){}
  try{ if(typeof _rt17LoadServer==="function") requestAnimationFrame(()=>setTimeout(()=>_rt17LoadServer(),0)); }catch(e){}
  const _rt18EdPath=/^\/(brief|report|research)\/[^/]+\/?$/.test(location.pathname);
  let _rt18EdDone=false; editorialReady.then(()=>{_rt18EdDone=true;});
  await Promise.race([editorialReady,new Promise(r=>setTimeout(r,_rt18EdPath?4000:150))]);
  if(!_rt18EdDone)editorialReady.then(()=>{try{if(pg==="home"){if(IS_DESKTOP())_desktopRoute("home");else renderMain();}}catch(e){}});
  _userTierReady=true;
  _enhanceInitialEditorialRoute();
  // The first boot intentionally waits for /api/me. If it was a signed-in
  // session, replace the public SEO shell with exactly one terminal surface
  // after the account result is known.
  const publicPage = _publicPageFromPath(location.pathname);
  if (_userSignedIn && publicPage && !location.pathname.match(/^\/(brief|report|research)\/[^/]+\/?$/)) {
    nav(publicPage, { history: "none" });
  } else {
    _syncFrontDoorMode();
  }
  renderAuthButtons();
  if ((pg === "gold" || pg === "playbook") && !_goldDeskLoad && !_goldDesk) {
    loadGoldDesk(false);
  }
  if (pg === "home") {
    _syncFrontDoorMode();
    if (IS_DESKTOP()) _desktopRoute("home");
    else renderMain();
  }
  _finishAppBoot();
  if (window._rt19WantSettings) { window._rt19WantSettings = false; setTimeout(() => { try { if (!document.getElementById("settingsOv")) openSettings(); history.replaceState(history.state, "", "/settings/"); } catch (e) {} }, 0); }
}

function _finishAppBoot(){
  document.body.classList.remove("app-booting");
  document.getElementById("dispatchBootLoader")?.remove();
}

function _showInitializationError(error) {
  console.error("Dispatch initialization failed", error);
  document.body.classList.remove("front-door-mode", "public-document-mode");
  _finishAppBoot();
  document.getElementById("dispatchInitError")?.remove();
  const notice = document.createElement("div");
  notice.id = "dispatchInitError";
  notice.className = "dispatch-init-error";
  notice.setAttribute("role", "alert");
  notice.innerHTML = `<strong>The Dispatch could not finish loading.</strong><span>Your session and saved data have not been changed.</span><button type="button" onclick="location.reload()">Try again</button>`;
  document.body.appendChild(notice);
}

function _isPremium(){
  if(_userTierReady)return _userAdmin===true||_userTier==="premium";
  return document.cookie.split(";").some(c=>c.trim().startsWith("td_tier=premium"));
}

async function _openBillingPortal(){
  try{
    const res=await fetch("/api/billing-portal",{method:"POST",credentials:"include"});
    const d=await res.json();
    if(d.url)window.location.href=d.url;
    else showToast(d.error||"Billing portal unavailable","var(--rd)");
  }catch(e){showToast("Could not open billing portal","var(--rd)");}
}

function _handleApiError(res,feature){
  if(res.status===401){_showLoginGate(feature);return "auth";}
  if(res.status===503)return "capacity";
  if(res.status===502)return "parse";
  return "error";
}

