const PUBLIC_PAGE_PATHS = Object.freeze({
  home: "/",
  dash: "/dashboard/",
  brief: "/brief/",
  playbook: "/playbook/",
  gold: "/gold/",
  mkt: "/markets/",
  news: "/news/",
  research: "/research/",
  sig: "/signals/",
  learn: "/learn/",
  port: "/portfolio/",
  watch: "/watchlist/",
  lab: "/lab/",
  scr: "/screener/",
  sectors: "/sectors/",
  heat: "/heatmap/",
  crypto: "/crypto/",
  paper: "/paper/",
  geo: "/geo/",
});
const PUBLIC_PATH_PAGES = Object.freeze(Object.fromEntries(
  Object.entries(PUBLIC_PAGE_PATHS).flatMap(([page, route]) => route === "/" ? [[route, page]] : [[route, page], [route.slice(0, -1), page]]),
));
const PUBLIC_PAGE_SEO_KEYS = Object.freeze({ mkt: "markets", sig: "signals" });
let PUBLIC_PAGE_SEO = {};
try {
  PUBLIC_PAGE_SEO = JSON.parse(document.getElementById("dispatch-public-seo")?.textContent || "{}");
} catch (e) {
  PUBLIC_PAGE_SEO = {};
}
function _publicPageFromPath(pathname) {
  return PUBLIC_PATH_PAGES[pathname] || (/^\/(?:brief|report|research)\/[a-z0-9-]+\/?$/.test(pathname) ? "research" : null);
}
function _setPublicMeta(selector, value) {
  const node = document.querySelector(selector);
  if (node) node.setAttribute("content", value);
}
function _syncPublicDocumentSeo(page) {
  const seo = PUBLIC_PAGE_SEO[PUBLIC_PAGE_SEO_KEYS[page] || page];
  if (!seo) return;
  const origin = "https://thedispatch.uk";
  const canonical = origin + seo.path;
  document.title = seo.title;
  document.documentElement.dataset.publicRoute = page;
  document.querySelector('link[rel="canonical"]')?.setAttribute("href", canonical);
  _setPublicMeta('meta[name="description"]', seo.description);
  _setPublicMeta('meta[property="og:type"]', seo.type === "Article" ? "article" : "website");
  _setPublicMeta('meta[property="og:title"]', seo.title);
  _setPublicMeta('meta[property="og:description"]', seo.description);
  _setPublicMeta('meta[property="og:url"]', canonical);
  _setPublicMeta('meta[name="twitter:title"]', seo.title);
  _setPublicMeta('meta[name="twitter:description"]', seo.description);

  const pageSchema = {
    "@context": "https://schema.org",
    "@type": seo.type,
    "@id": canonical + "#page",
    name: seo.title,
    url: canonical,
    description: seo.description,
    isPartOf: { "@type": "WebSite", name: "The Dispatch Markets", url: origin + "/" },
    publisher: { "@type": "Person", name: "Vraj Patel", url: "https://www.linkedin.com/in/VRAJ2710" },
  };
  if (page === "home") {
    pageSchema.potentialAction = {
      "@type": "ReadAction",
      target: Object.values(PUBLIC_PAGE_SEO).filter(item => item.path !== "/").map(item => origin + item.path),
    };
  }
  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "The Dispatch Markets", item: origin + "/" },
      ...(page === "home" ? [] : [{ "@type": "ListItem", position: 2, name: seo.h1, item: canonical }]),
    ],
  };
  const pageScript = document.getElementById("dispatch-page-schema");
  const breadcrumbScript = document.getElementById("dispatch-breadcrumb-schema");
  if (pageScript) pageScript.textContent = JSON.stringify(pageSchema);
  if (breadcrumbScript) breadcrumbScript.textContent = JSON.stringify(breadcrumbSchema);
}
function _syncPublicPageUrl(page, mode) {
  const route = PUBLIC_PAGE_PATHS[page];
  if (!route || location.pathname === route) return;
  history[mode === "replace" ? "replaceState" : "pushState"]({ dispatchPage: page }, "", route);
}
function _setATab(t){aTab=t;if(IS_DESKTOP())renderP2();else renderMain();_rt22TabIntoView();}
function _rt22TabIntoView(){requestAnimationFrame(()=>document.querySelectorAll(".tabs > button.on").forEach(b=>{const s=b.parentElement;if(s&&s.scrollWidth>s.clientWidth)s.scrollLeft=Math.max(0,b.offsetLeft-s.offsetLeft-(s.clientWidth-b.offsetWidth)/2);}));}
function nav(p, options = {}){
  if(pg==='mkt'&&p!=='mkt'){_mktView='curated';_mktSearch='';_mktFilter='all';_mktSort='default';}
  if(!IS_DESKTOP())_siteIntel.expanded=false;
  // Keep research report selection when opening research; clear otherwise
  if(p!=='research') selReport=null;
  pg=p;selTk=null;aTab="ov";comRes=null;comErr="";_learnSub=null;_dynTk=null;_dynData=null;_dynLoading=false;
  // Update the live route marker before deciding which renderer owns the
  // page. This matters when a mobile visitor returns Home from a product URL:
  // the boot-time data-public-route may still name the product page.
  _syncPublicDocumentSeo(p);
  _syncFrontDoorMode(p);
  if (_isPublicDocumentVisitor(p)) {
    _closeDeskOverlays();
    if (options.history !== "none") _syncPublicPageUrl(p, options.history);
    if (p === "home") {
      if (IS_DESKTOP()) {
        _desktopRoute("home");
      } else {
        const main = document.getElementById("main");
        if (main) main.innerHTML = renderPublicHome();
      }
    }
    renderNav();
    return;
  }
  if (p === "brief") {
    _trackDispatchEvent("brief_opened", { location: "navigation" });
  }
  if (options.history !== "none") _syncPublicPageUrl(p, options.history);
  _pushRecentNav(p);

  // Desktop: route to overlays/panels (main is hidden). Mobile: render multi-page shell.
  const deskHandled = _desktopRoute(p);
  if (!deskHandled) {
    renderMain();
    if (pg === "lab") _initLabPage();
  }
  renderNav();
  if (IS_DESKTOP()) updateSidebarActive();
  document.querySelector(".main")?.scrollTo(0,0);
  if(p==='lab'&&_sectorNeedsFetch())fetchSectorData();
  if(p==='dash'){if(_sectorNeedsFetch())fetchSectorData();loadDispatchBrief(false);if(!_earnRadar&&!_earnRadarLoad)loadEarningsRadar();}
  if(p==='gold'||p==='playbook'){loadGoldDesk(false);}
  if(p==='brief'){loadDispatchBrief(false);}
  _paintWlGlance();

  document.querySelectorAll('#mainNav a').forEach(a => {
    a.classList.toggle('active', a.dataset.nav === p || a.dataset.section === p || (p==='dash' && (a.dataset.nav==='briefing'||a.dataset.section==='briefing')));
  });

  if(p==='crypto'&&!_cryptoMktData&&!_cryptoMktLoading)fetchCryptoMarket();
  if(p==='news'&&!newsLastFetch&&!newsFetching)fetchLiveNews();
  if(p==='paper'){
    if(!newsLastFetch&&!newsFetching)fetchLiveNews();
    if(!_brief&&!_briefLoad)loadDispatchBrief(false);
  }
  if(p==='geo'){
    _paintChokepointStrip();
    if(!deskHandled) _fetchGeoEarthquakes();
  }
  _onPageIntel(_INTEL_PAGE_MAP[p] || "pulse");
  _updateSmartDock();
}

window.addEventListener("popstate", () => {
  const page = _publicPageFromPath(location.pathname);
  if (page) nav(page, { history: "none" });
});

// Wire optional top bar (if present) — must not shadow global nav()
function wireTopNav() {
  const bar = document.getElementById('mainNav');
  if (!bar || bar.dataset.wired) return;
  bar.dataset.wired = 'true';
  bar.addEventListener('click', (e) => {
    const link = e.target.closest('a');
    if (!link) return;
    const target = link.dataset.nav || link.dataset.section;
    if (!target) return;
    e.preventDefault();
    if (target === 'briefing') nav('dash');
    else if (target === 'markets') nav('mkt');
    else if (target === 'research') nav('research');
    else if (target === 'news') nav('news');
    else if (target === 'intel') nav('intel');
    else if (target === 'lab') nav('lab');
    else if (target === 'port' || target === 'portfolio') nav('port');
    else nav(target);
  });
}

// Enhance global search to feel like a real command palette
function enhanceCommandPalette() {
  const inp = document.getElementById('globalSearch');
  if (!inp || inp.dataset.enhanced) return;
  inp.dataset.enhanced = 'true';
  inp.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && inp.value.trim()) {
      const raw = inp.value.trim();
      const q = (typeof resolveInternalTicker === "function" ? resolveInternalTicker(raw) : "") || sanitizeTicker(raw) || raw.toUpperCase();
      inp.value = '';
      const match = A.find(a => a.tk === q) || IDX.find(i => i.tk === q);
      if (match) {
        openA(q);
      } else if (q) {
        // Dyn / international symbols — never dump analysts to Newsroom by mistake
        lookupTicker(q);
      } else {
        openSearch();
      }
    }
  });
}

