let _searchDebounce=null,_searchLastQ="";
function _paintSearchResults(raw,r){
  const el=document.getElementById("sres");
  if(!el)return;
  _searchIdx=-1;
  r.sort((a,b)=>(b.priority||0)-(a.priority||0));
  el.innerHTML=r.length?r.slice(0,12).map(x=>`<button type="button" class="sres${x.tp==='Command'?' sres-cmd':''}" onclick="${x.act}"><span class="sres-nm">${_escHtml(x.nm)}</span>${x.sub?`<span class="sres-d">${_escHtml(x.sub)}</span>`:""}${x.tk?_searchPriceBadge(x.tk):""}${x.tk?_smartFitBadge(x.tk):""}${bd(x.tp,x.tp==="Research"?"var(--gd)":x.tp==="Command"?"var(--pu)":x.tp==="Lookup"?"var(--cy)":"var(--bl)")}</button>`).join(""):`<div class="sres-empty">No results for “${_escHtml(raw)}” — try AAPL, brief, lab, or sync</div>`;
}
function _buildLocalSearchHits(raw){
  const q=raw.toLowerCase();
  let r=[];
  SMART_COMMANDS.forEach(c=>{if(c.k.includes(q)||c.l.toLowerCase().includes(q)||c.d.toLowerCase().includes(q))r.push({nm:c.l,sub:c.d,tp:"Command",act:c.act,priority:2});});
  A.forEach(a=>{if(a.tk.toLowerCase().includes(q)||a.nm.toLowerCase().includes(q))r.push({nm:`${a.tk} — ${a.nm}`,sub:a.cat,tp:a.cat,act:`openA('${a.tk}');closeSearch()`,tk:a.tk,priority:liveSymbols.has(a.tk)?1:0});});
  REPORTS.forEach(rep=>{if(rep.headline.toLowerCase().includes(q)||rep.deck.toLowerCase().includes(q)||rep.tags.some(t=>t.toLowerCase().includes(q)))r.push({nm:rep.headline.replace(/<[^>]*>/g,""),sub:"Research report",tp:"Research",act:`nav('research');openReport('${rep.id}');closeSearch()`,priority:0});});
  const resolved=typeof resolveInternalTicker==="function"?resolveInternalTicker(raw):sanitizeTicker(raw);
  if(resolved){
    const a=A.find(x=>x.tk===resolved);
    if(a&&!r.some(x=>x.tk===a.tk)){
      r.unshift({nm:`${a.tk} — ${a.nm}`,sub:a.cat+" · desk",tp:a.cat,act:`openA('${a.tk}');closeSearch()`,tk:a.tk,priority:3});
    }else if(!a&&!r.some(x=>x.tk===resolved)){
      r.unshift({nm:resolved,sub:"Open on desk / Yahoo",tp:"Lookup",act:`lookupTicker('${resolved}');closeSearch()`,tk:resolved,priority:3});
    }
  }
  try{
    const book=new Set([...(getActiveWl().tickers||[]),...portfolio.map(p=>p.tk)]);
    book.forEach(tk=>{
      if(!tk||r.some(x=>x.tk===tk))return;
      if(String(tk).toUpperCase().includes(q.toUpperCase())||String(tk).toLowerCase().includes(q)){
        const a=A.find(x=>x.tk===tk);
        r.push({nm:a?`${a.tk} — ${a.nm}`:tk,sub:a?a.cat+" · book":"Book",tp:a?.cat||"Book",act:`openA('${tk}');closeSearch()`,tk,priority:2});
      }
    });
  }catch(e){}
  return _rt24RankHits(r,raw);
}
function doSearch(q){
  const el=document.getElementById("sres");
  if(!el)return;
  _searchIdx=-1;
  if(!q){el.innerHTML=_renderSmartSearchDefault();clearTimeout(_searchDebounce);_searchLastQ="";return;}
  const raw=_rt30Q(q);
  _searchLastQ=raw;
  const local=_buildLocalSearchHits(raw);
  _paintSearchResults(raw,local.slice());
  // Debounced Yahoo search — parity with desktop cmd autocomplete (RELIANCE → RELIANCE.NS)
  clearTimeout(_searchDebounce);
  _searchDebounce=setTimeout(async()=>{
    if(_searchLastQ!==raw)return;
    try{
      const res=await fetch(`/api/search?q=${encodeURIComponent(raw)}`,{signal:AbortSignal.timeout(4000)});
      if(!res.ok||_searchLastQ!==raw)return;
      const data=await res.json();
      if(_searchLastQ!==raw)return;
      const hits=_buildLocalSearchHits(raw);
      const seen=new Set(hits.map(x=>x.tk).filter(Boolean));
      const ranked=[...((data.result||[]))];
      // Promote best match for bare query to front of Yahoo hits
      const best=_bestYahooSearchMatch(ranked,raw);
      if(best){
        const bi=ranked.findIndex(x=>x.symbol===best.symbol);
        if(bi>0){ranked.splice(bi,1);ranked.unshift(best);}
      }
      ranked.slice(0,8).forEach(g=>{
        if(!g?.symbol||seen.has(g.symbol))return;
        const desk=resolveInternalTicker(g.symbol)||g.symbol;
        if(seen.has(desk))return;
        seen.add(g.symbol);seen.add(desk);
        const known=A.find(a=>a.tk===desk);
        // Prefer exchange-suffixed best match over weak bare lookups
        const isBest=best&&g.symbol===best.symbol;
        if(known){
          hits.push({nm:`${known.tk} — ${known.nm}`,sub:known.cat+" · Yahoo",tp:known.cat,act:`openA('${known.tk}');closeSearch()`,tk:known.tk,priority:isBest?3:2});
        }else{
          hits.push({nm:`${g.symbol} — ${g.name||g.symbol}`,sub:(g.exchange||"Yahoo")+" · global",tp:"Lookup",act:`lookupTicker('${g.symbol}');closeSearch()`,tk:g.symbol,priority:isBest?3:2});
        }
      });
      _paintSearchResults(raw,hits);
    }catch(e){}
  },300);
}
function togWatch(tk){
  tk=(typeof resolveInternalTicker==="function"?resolveInternalTicker(tk):tk)||tk;
  const wl=getActiveWl();
  if(wl.tickers.includes(tk)){removeFromWatchlist(tk);}
  else{addToWatchlist(tk);}
  // Keep legacy watch in sync for compatibility
  watch=getActiveWl().tickers;
  _paintWlGlance();
  renderMain();
  if(IS_DESKTOP())renderP4();
}
function isWatched(tk){
  const raw=String(tk||"").trim();
  if(!raw)return false;
  const sym=(typeof resolveInternalTicker==="function"?resolveInternalTicker(raw):"")||sanitizeTicker(raw)||raw;
  const tks=getActiveWl().tickers||[];
  if(tks.includes(sym)||tks.includes(raw))return true;
  // Match aliases both ways (list may hold BTC while UI checks BTC-USD)
  return tks.some(t=>{
    const r=(typeof resolveInternalTicker==="function"?resolveInternalTicker(t):"")||t;
    return r===sym||t===sym||r===raw;
  });
}
function saveReason(e){
  const day=String(e?.ts||new Date().toISOString()).slice(0,10);
  reason=reason.filter(r=>!(r.ticker===e.ticker&&String(r.ts||"").slice(0,10)===day&&r.verdict===e.verdict));
  reason.unshift(e);
  if(reason.length>50)reason.length=50;
  localStorage.setItem("td_r",JSON.stringify(reason));
}

// ═══════════════════════════════════════════════════════════
// INVESTING LENSES
// ═══════════════════════════════════════════════════════════
async function runCommittee(tk){
  if(!_isPremium()){_showLoginGate('Investing Lenses');return;}
  comLoad=true;comRes=null;comErr="";lensMeta=null;lensIntel=null;renderMain();
  const a=A.find(x=>x.tk===tk)||{nm:tk,th:'No thesis available.',sc:50,se:'Neutral',cat:'Unknown'};
  const userThesis=lensThesis[tk]||'';
  await _prefetchLensData(tk);
  const context=_buildLensContext(tk);
  try{
    const out=await _callLensEngine(tk,a,context,userThesis);
    if(out.auth){comLoad=false;_showLoginGate('Investing Lenses');renderMain();return;}
    comRes=out.lenses;lensIntel=out.intelligence;
    lensMeta=_lensMetaFromResult(_getLensMembers(out.lenses),context,userThesis,out.meta);
    const synth=_getSynthesis(out.lenses);
    const re=_computeRegimeEngine();
    saveLensRun({ticker:tk,thesis:synth?.analysis||out.intelligence?.analysis||a.th,verdict:synth?.verdict||"MONITOR",ts:new Date().toISOString(),sc:a.sc,regime:re.label,lenses:_getLensMembers(out.lenses)?.length||5});
  }catch(e){
    comErr = true;
  }
  if(selTk!==tk||pg!=='anlz'){comLoad=false;return;}
  comLoad=false;renderMain();
}

// ═══════════════════════════════════════════════════════════
// PAGE: GOLD DESK + WEEKLY PLAYBOOK (Product V1 core)
// ═══════════════════════════════════════════════════════════
let _goldDesk = null;
let _goldDeskLoad = false;
let _goldDeskErr = null;
let _goldDeskFetchedAt = 0;
let _goldTab = "playbook"; // playbook | desk
// The ladder reads this on first paint, before any scenario button is clicked.
// Without a declaration here it is only created by setGoldScenario(), so
// rendering Playbook cold threw ReferenceError and the page stayed blank.
let _goldScenario = "bullish"; // bullish | bearish | range

async function loadGoldDesk(force) {
  if (_goldDeskLoad) return;
  if (!force && _goldDesk && Date.now() - _goldDeskFetchedAt < 120000) {
    try { if (_isPremium()) _gdLoadHist(); } catch (_) {}
    if (pg === "gold") _refreshGoldView();
    return;
  }
  if (!_userTierReady) return;
  if (!_isPremium()) {
    _goldDeskErr = "Premium membership required";
    if (pg === "gold" || pg === "playbook") _refreshGoldView();
    return;
  }
  try { _gdLoadHist(force); } catch (_) {}
  _goldDeskLoad = true;
  _goldDeskErr = null;
  if (pg === "gold" || pg === "playbook") _refreshGoldView();
  try {
    const opts = {};
    try {
      if (typeof AbortSignal !== "undefined" && typeof AbortSignal.timeout === "function") {
        opts.signal = AbortSignal.timeout(25000);
      }
    } catch (_) {}
    const res = await fetch("/api/gold-desk", opts);
    const text = await res.text();
    let data = null;
    try {
      data = JSON.parse(text);
    } catch (_) {
      throw new Error(
        res.ok
          ? "Gold API returned HTML instead of JSON — try hard-refresh"
          : `Gold API HTTP ${res.status}`
      );
    }
    if (!res.ok || data.error) {
      if (res.status === 401 || data.error === "Premium membership required") {
        throw new Error("Premium membership required");
      }
      throw new Error("gold desk response could not be published");
    }
    _goldDesk = data;
    _goldDeskFetchedAt = Date.now();
    try {
      localStorage.setItem("td_gold_playbook", JSON.stringify({
        weekId: data.playbook?.weekId,
        weekLabel: data.playbook?.weekLabel,
        savedAt: Date.now(),
        playbook: data.playbook,
      }));
    } catch (_) {}
  } catch (e) {
    _goldDeskErr = e?.message === "Premium membership required"
      ? "Premium membership required"
      : "AI response could not be published";
  }
  _goldDeskLoad = false;
  if (pg === "gold" || pg === "playbook") _refreshGoldView();
}

function _refreshGoldView() {
  // Both gold surfaces share one payload, so either overlay may be the live one.
  const surfaces = { goldOv: renderGoldDesk, playbookOv: renderPlaybook };
  if (IS_DESKTOP()) {
    for (const id of Object.keys(surfaces)) {
      const ov = document.getElementById(id);
      if (!ov) continue;
      ov.classList.add("term-overlay-gold");
      const body = ov.querySelector(".term-overlay-body");
      if (body) {
        body.innerHTML = surfaces[id]();
        return;
      }
    }
    // Overlay missing on desktop — recreate via route
    if (pg === "gold" || pg === "playbook") {
      _desktopRoute(pg);
      return;
    }
  }
  if (pg === "gold" || pg === "playbook") renderMain();
}

function setGoldScenario(s) {
  _goldScenario = ["bullish", "bearish", "range"].includes(s) ? s : "bullish";
  _refreshGoldView();
}

// Kept as a redirect: the tabs became destinations, but older entry points
// (command palette, saved links, onboarding) still call this.
function setGoldTab(t) {
  nav(t === "desk" ? "gold" : "playbook");
}

function _gdPx(n) {
  if (n == null || !isFinite(n)) return "—";
  return Number(n).toLocaleString(undefined, { maximumFractionDigits: 2 });
}

function _gdChg(n) {
  if (n == null || !isFinite(n)) return "";
  const s = n >= 0 ? "+" : "";
  return `${s}${n.toFixed(2)}%`;
}

function _gdSpark(arr) {
  if (!arr || arr.length < 2) return "";
  const w = 160, h = 36, pad = 2;
  const min = Math.min(...arr), max = Math.max(...arr);
  const span = max - min || 1;
  const pts = arr.map((v, i) => {
    const x = pad + (i / (arr.length - 1)) * (w - pad * 2);
    const y = pad + (1 - (v - min) / span) * (h - pad * 2);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(" ");
  const up = arr[arr.length - 1] >= arr[0];
  return `<svg class="gd-spark" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" aria-hidden="true"><polyline fill="none" stroke="${up ? "var(--gn)" : "var(--rd)"}" stroke-width="1.5" points="${pts}"/></svg>`;
}

// rt14: the desk's levels, sessions and volatility come from COMEX gold futures (GC=F) daily bars through the
// existing cached /api/yahoo-chart proxy: one request per gold visit (10-min client cache, one retry), never polled.
let _gdHist = null, _gdHistAt = 0, _gdHistLoad = false, _gdHistErrAt = 0;
async function _gdLoadHist(force) {
  if (_gdHistLoad) return;
  const age = Date.now() - _gdHistAt;
  if (_gdHist && age < (force ? 60_000 : 600_000)) return;
  if (!force && _gdHistErrAt && Date.now() - _gdHistErrAt < 60_000) return;
  _gdHistLoad = true;
  let st = null;
  try {
    for (let i = 0; i < 2 && !st; i++) {
      if (i) await new Promise(r => setTimeout(r, 5000));
      try {
        const r = await fetch("/api/yahoo-chart?symbol=GC%3DF&range=6mo&interval=1d");
        const j = r.ok ? await r.json() : null;
        st = _gdStats(j?.chart?.result?.[0]);
      } catch (_) {}
    }
  } finally { _gdHistLoad = false; }
  if (st) { _gdHist = st; _gdHistAt = Date.now(); _gdHistErrAt = 0; } else _gdHistErrAt = Date.now();
  if (pg === "gold" || pg === "playbook") _refreshGoldView();
}
function _gdStats(res) {
  const q = res?.indicators?.quote?.[0], ts = res?.timestamp;
  if (!q || !Array.isArray(ts)) return null;
  const ok = v => typeof v === "number" && isFinite(v) && v > 0;
  const bars = [];
  for (let i = 0; i < ts.length; i++) {
    const o = q.open?.[i], hi = q.high?.[i], lo = q.low?.[i], c = q.close?.[i];
    if (ok(o) && ok(hi) && ok(lo) && ok(c) && hi >= lo) bars.push({ t: ts[i] * 1000, h: hi, l: lo, c });
  }
  if (bars.length < 30) return null;
  const meta = res.meta || {};
  const last = bars[bars.length - 1], prev = bars[bars.length - 2];
  const px = ok(meta.regularMarketPrice) ? meta.regularMarketPrice : last.c;
  const done = bars.slice(0, -1); // the latest bar may still be trading
  const tr = [];
  for (let i = 1; i < done.length; i++) { const b = done[i], pc = done[i - 1].c; tr.push(Math.max(b.h - b.l, Math.abs(b.h - pc), Math.abs(b.l - pc))); }
  const atr = tr.length >= 14 ? tr.slice(-14).reduce((a, b) => a + b, 0) / 14 : null;
  const closes = done.map(b => b.c);
  const rets = [];
  for (let i = Math.max(1, closes.length - 20); i < closes.length; i++) rets.push(Math.log(closes[i] / closes[i - 1]));
  let rv = null;
  if (rets.length >= 19) { const m = rets.reduce((a, b) => a + b, 0) / rets.length; rv = Math.sqrt(rets.reduce((a, b) => a + (b - m) ** 2, 0) / (rets.length - 1) * 252) * 100; }
  const sma = n => closes.length >= n ? closes.slice(-n).reduce((a, b) => a + b, 0) / n : null;
  const sma20 = sma(20), sma50 = sma(50);
  // Swing pivots: a session whose high (low) is above (below) the two sessions either side; last 90 sessions.
  const win = done.slice(-90), hiP = [], loP = [];
  for (let i = 2; i < win.length - 2; i++) {
    const b = win[i], nb = [win[i - 2], win[i - 1], win[i + 1], win[i + 2]];
    if (nb.every(x => b.h > x.h)) hiP.push(b.h);
    if (nb.every(x => b.l < x.l)) loP.push(b.l);
  }
  const near = 0.003;
  const touches = (L, k) => win.filter(b => Math.abs(b[k] - L) / L <= near).length;
  const uniq = arr => { const out = []; arr.forEach(v => { if (!out.some(x => Math.abs(x - v) / v <= near)) out.push(v); }); return out; };
  const resL = uniq(hiP.filter(v => v > px * 1.001).sort((a, b) => a - b)).slice(0, 2).map(v => ({ level: v, hits: touches(v, "h") }));
  const supL = uniq(loP.filter(v => v < px * 0.999).sort((a, b) => b - a)).slice(0, 2).map(v => ({ level: v, hits: touches(v, "l") }));
  let trend = "mixed trend";
  if (sma20 && sma50) {
    if (px > sma20 && sma20 > sma50) trend = "uptrend";
    else if (px < sma20 && sma20 < sma50) trend = "downtrend";
  }
  const atrPct = atr ? atr / px * 100 : null;
  const cond = atrPct == null ? null : atrPct < 0.9 ? "low" : atrPct <= 1.8 ? "normal" : "elevated";
  const sessHigh = ok(meta.regularMarketDayHigh) ? Math.max(meta.regularMarketDayHigh, last.h) : last.h;
  const sessLow = ok(meta.regularMarketDayLow) ? Math.min(meta.regularMarketDayLow, last.l) : last.l;
  const mt = Number(meta.regularMarketTime) > 0 ? Number(meta.regularMarketTime) * 1000 : last.t;
  return { px, prevClose: prev.c, chgPct: prev.c ? (px / prev.c - 1) * 100 : null,
    sessDate: last.t, sessHigh, sessLow, prevDate: prev.t, prevHigh: prev.h, prevLow: prev.l,
    atr, atrPct, rv, sma20, sma50, trend, cond, sup: supL, res: resL, asOf: mt };
}
function _gdStructText(s) {
  const f = v => `$${_gdPx(Math.round(v * 10) / 10)}`;
  const out = [];
  if (s.chgPct != null) out.push(`COMEX gold futures are ${s.chgPct >= 0 ? "up" : "down"} ${Math.abs(s.chgPct).toFixed(2)}% on the session (${f(s.px)} vs ${f(s.prevClose)} prior close).`);
  if (s.sma20 && s.sma50) out.push(`Price is ${s.px >= s.sma20 ? "above" : "below"} its 20-day average (${f(s.sma20)}) and ${s.px >= s.sma50 ? "above" : "below"} its 50-day average (${f(s.sma50)}).`);
  if (s.atr) out.push(`Daily ranges are ${s.cond}: ATR(14) ${f(s.atr)}, ${s.atrPct.toFixed(1)}% of price.`);
  return out.join(" ");
}
function _gdVpBars(bins) {
  if (!bins || !bins.length) return `<div class="gd-muted">Volume profile unavailable on this feed.</div>`;
  return `<div class="gd-vp">${bins.map(b => {
    const pct = Math.max(4, (b.rel || 0) * 100);
    return `<div class="gd-vp-row" title="${_gdPx(b.low)}–${_gdPx(b.high)}"><div class="gd-vp-bar" style="width:${pct}%"></div><span class="gd-vp-lbl">${_gdPx(b.low)}</span></div>`;
  }).join("")}</div>`;
}

// ═══════════════════════════════════════════════════════════
// THE LADDER — the Gold Desk hero.
//
// Every number the desk computes is a PRICE, and prices have a natural
// spatial order. Printed as sentences they read as trivia; printed on one
// shared axis they answer the only question that matters: where is spot, and
// what breaks the thesis.
//
// Everything is placed at true proportional distance. Nothing is schematic.
// ═══════════════════════════════════════════════════════════
function _ladderScale(d) {
  const px = d?.gold?.price;
  if (!Number.isFinite(px)) return null;
  const pts = [px];
  const push = (v) => { if (Number.isFinite(v)) pts.push(v); };

  (d.levels?.support || []).forEach((s) => push(s.level));
  (d.levels?.resistance || []).forEach((r) => push(r.level));
  push(d.sessions?.sessionHigh); push(d.sessions?.sessionLow);
  push(d.sessions?.priorDayHigh); push(d.sessions?.priorDayLow);
  const named = d.sessions?.named;
  if (named) ["asia", "london", "newYork"].forEach((k) => { push(named[k]?.high); push(named[k]?.low); });
  const vp = d.volumeProfile;
  if (vp?.bins?.length) { push(vp.bins[0].low); push(vp.bins[vp.bins.length - 1].high); }
  push(vp?.poc); push(vp?.vah); push(vp?.val);
  Object.values(d.playbook?.scenarios || {}).forEach((s) =>
    (s?.targets || []).forEach(push));

  let lo = Math.min(...pts), hi = Math.max(...pts);
  if (!(hi > lo)) { lo = px * 0.99; hi = px * 1.01; }
  const pad = (hi - lo) * 0.06;
  return { lo: lo - pad, hi: hi + pad };
}

function _renderLadder(d) {
  const sc = _ladderScale(d);
  if (!sc) return "";
  const px = d.gold.price;

  const W = 760, H = 470, TOP = 26, BOT = 438;
  const AX = 176;              // the axis
  const RIGHT = 560;           // where level rules stop
  const y = (p) => TOP + ((sc.hi - p) / (sc.hi - sc.lo)) * (BOT - TOP);
  const fmt = (p) => (+p).toFixed(2);

  let g = "";

  // Sessions, furthest back: Asia / London / New York as bands at their range.
  const named = d.sessions?.named;
  const SESS = [["asia", "ASIA"], ["london", "LONDON"], ["newYork", "NEW YORK"]];
  if (named) {
    SESS.forEach(([k, label], i) => {
      const s = named[k];
      if (!s || !Number.isFinite(s.high) || !Number.isFinite(s.low)) return;
      const yh = y(s.high), yl = y(s.low);
      const x = AX + 8 + i * 22;
      g += `<rect class="ladder-session" x="${x}" y="${yh.toFixed(1)}" width="16" height="${Math.max(1, yl - yh).toFixed(1)}" rx="2"><title>${label} ${fmt(s.low)}–${fmt(s.high)}</title></rect>`;
      g += `<text class="ladder-lbl-k" x="${x + 8}" y="${(BOT + 14).toFixed(1)}" text-anchor="middle">${label.slice(0, 3)}</text>`;
    });
  }

  // Volume profile — the shape of where trade actually happened.
  const vp = d.volumeProfile;
  if (vp?.bins?.length) {
    vp.bins.forEach((b) => {
      if (!Number.isFinite(b.low) || !Number.isFinite(b.high)) return;
      const yh = y(b.high), yl = y(b.low);
      const w = Math.max(1, (b.rel || 0) * 150);
      const isPoc = Number.isFinite(vp.poc) && vp.poc >= b.low && vp.poc <= b.high;
      g += `<rect class="${isPoc ? "ladder-vp-poc" : "ladder-vp"}" x="${(AX - 8 - w).toFixed(1)}" y="${yh.toFixed(1)}" width="${w.toFixed(1)}" height="${Math.max(1, yl - yh - 1).toFixed(1)}"><title>${fmt(b.low)}–${fmt(b.high)}</title></rect>`;
    });
    if (Number.isFinite(vp.poc)) {
      // POC and spot converge exactly when the reading matters most, so nudge
      // the label clear rather than letting the two overprint.
      const yp = y(vp.poc), ysp = y(px);
      const off = Math.abs(yp - ysp) < 15 ? (yp <= ysp ? -13 : 15) : -4;
      g += `<text class="ladder-lbl-k" x="${AX - 12}" y="${(yp + off).toFixed(1)}" text-anchor="end">POC ${fmt(vp.poc)}</text>`;
    }
  }

  g += `<line class="ladder-axis" x1="${AX}" y1="${TOP}" x2="${AX}" y2="${BOT}"/>`;

  // Levels. Labels are nudged apart so a dense cluster stays readable —
  // the RULE stays at the true price, only the text moves.
  const marks = [];
  (d.levels?.resistance || []).forEach((r, i) =>
    marks.push({ p: r.level, kind: "r", key: "R" + (i + 1), note: r.strength || "" }));
  (d.levels?.support || []).forEach((s, i) =>
    marks.push({ p: s.level, kind: "s", key: "S" + (i + 1), note: s.strength || "" }));

  marks.sort((a, b) => b.p - a.p);
  let lastY = -99;
  marks.forEach((m) => {
    if (!Number.isFinite(m.p)) return;
    const yy = y(m.p);
    const ly = Math.max(yy, lastY + 13);
    lastY = ly;
    g += `<line class="ladder-tick ladder-tick-${m.kind}" x1="${AX}" y1="${yy.toFixed(1)}" x2="${RIGHT}" y2="${yy.toFixed(1)}"/>`;
    g += `<text class="ladder-lbl" x="${RIGHT + 10}" y="${(ly + 3.5).toFixed(1)}"><tspan class="ladder-lbl-k">${m.key}</tspan>  ${fmt(m.p)}${m.note ? `  ${m.note}` : ""}</text>`;
  });

  // Targets for the scenario currently on screen. Real numbers only —
  // invalidation is prose on the server, so it is not fabricated here.
  const scen = d.playbook?.scenarios || {};
  const active = scen[_goldScenario] || null;
  if (active?.targets?.length) {
    active.targets.forEach((t, i) => {
      if (!Number.isFinite(t)) return;
      const yy = y(t);
      const cls = _goldScenario === "bearish" ? "ladder-inval" : "ladder-target";
      g += `<path class="${cls}" d="M${AX - 4} ${yy.toFixed(1)} l-7 -4.5 v9 z" fill="currentColor" stroke="none"><title>${_goldScenario} target ${i + 1}: ${fmt(t)}</title></path>`;
    });
  }

  // Spot, struck across everything. The one moment of motion in the product.
  const ys = y(px);
  g += `<g class="ladder-spot">
    <line class="ladder-spot-line" x1="${AX - 18}" y1="${ys.toFixed(1)}" x2="${RIGHT + 4}" y2="${ys.toFixed(1)}"/>
    <text class="ladder-spot-lbl" x="${RIGHT + 10}" y="${(ys + 4).toFixed(1)}">${fmt(px)}</text>
  </g>`;

  const proxy = vp?.isProxy
    ? `<div class="gd-sm">Volume profile is a range-distributed proxy, not exchange volume-at-price.</div>`
    : "";

  return `<figure class="ladder-wrap">
    <svg class="ladder" viewBox="0 0 ${W} ${H}" role="img"
         aria-label="Price ladder: spot ${fmt(px)} against support, resistance, session ranges and volume profile">
      ${g}
    </svg>
    <figcaption class="ladder-key">
      <span><i class="k-spot"></i>Spot</span>
      <span><i class="k-r"></i>Resistance</span>
      <span><i class="k-s"></i>Support</span>
      <span><i class="k-vp"></i>Volume at price</span>
      <span><i class="k-sess"></i>Sessions</span>
    </figcaption>
    ${proxy}
  </figure>`;
}

// PRODUCT_V1 lists the automated dashboard and the weekly playbook as two
// separate pillars, and the whole visual system rests on published matter and
// live matter being different materials. Behind tabs on one page they were
// neither. They are now two destinations sharing one payload.
function renderPlaybook() { return _renderGoldSurface("playbook"); }
function renderGoldDesk() { return _renderGoldSurface("desk"); }

function _renderGoldSurface(mode) {
  const isPlay = mode === "playbook";
  const livePxN = typeof livePx === "function" ? livePx("XAU") : null;
  const hdrActions = ""; // rt14: Refresh lives in the hero footer (the header button + accent bar looked orphaned on phones)
  let h = _renderPgHdr(
    isPlay ? "Weekly Playbook" : "Gold Dashboard",
    isPlay
      ? "Conditional scenarios for the week · published Saturday"
      : "Gold structure · levels, sessions, volatility and macro",
    hdrActions
  );

  if (_goldDeskLoad && !_goldDesk) {
    h += `<div class="gc gd-card"><div class="gd-muted">Building gold structure and weekly playbook from delayed market data…</div></div>`;
    return h;
  }
  if (_goldDeskErr && !_goldDesk) {
    const premiumGate = _goldDeskErr === "Premium membership required";
    h += `<div class="gc gd-card">
      <div class="empty-title">${premiumGate ? `${_rt18PageName()} is part of Premium` : "Gold desk unavailable"}</div>
      ${premiumGate ? `<div class="empty-sub" style="margin-bottom:12px">${_rt18PageBlurb()}</div>` : ""}
      ${premiumGate
        ? `<div style="display:flex;gap:8px;flex-wrap:wrap">
            <a class="btn btn-ghost" href="/__auth/login">Sign in</a>
            <a class="btn btn-primary" href="/__auth/subscribe">Subscribe</a>
          </div>`
        : _renderAiRetryState("loadGoldDesk(true)", "gold desk")}
    </div>`;
    return h;
  }
  if (!_goldDesk) {
    h += `<div class="gc gd-card">
      <div class="empty-title">Load this week's gold playbook</div>
      <div class="empty-sub">Evidence-based scenarios · support/resistance · macro context · conditional language only</div>
      <button class="btn btn-primary" onclick="loadGoldDesk(true)">Generate playbook</button>
    </div>`;
    return h;
  }

  const d = _goldDesk;
  const g = d.gold || {};
  const gs = _gdHist; // rt14: COMEX GC=F daily-bar stats (null until loaded)
  const px = livePxN != null ? livePxN : g.price;
  // rt14: the hero % uses the tape's XAU basis (spot vs prior close). The desk payload's changePct comes from a
  // spot reference that carries no change, so a 0 there is "unknown", never "+0.00%".
  const lcN = typeof liveChg === "function" ? liveChg("XAU") : null;
  const aiBlind = !(Number.isFinite(g.changePct) && g.changePct !== 0); // the AI saw no price change at all
  const chg = lcN != null && lcN !== 0 ? lcN : (!aiBlind ? g.changePct : null);
  const chgCls = chg == null ? "px-flat" : chg >= 0 ? "px-up" : "px-dn";
  const aiAtr = !aiBlind && d.volatility?.atr14 > 0 ? d.volatility.atr14 : null;
  const heroSub = gs
    ? `${gs.trend} (20/50-day) · daily range ${gs.cond || "—"}${gs.atr ? ` (ATR $${_gdPx(Math.round(gs.atr * 10) / 10)}, futures)` : ""}`
    : aiAtr ? `${d.structure?.regime || "—"} · vol ${d.volatility?.condition || "—"} (ATR $${_gdPx(aiAtr)})` : "";
  const dxyPx = d.macro?.dxy?.px, dxyTxt = Number.isFinite(dxyPx) ? Number(dxyPx).toFixed(2) : "—";
  const aiAt = d.asOf ? _fmtAsOf(new Date(d.asOf).getTime()) : "";

  h += `<div class="gd-hero gc">
    <div class="gd-hero-top">
      <div>
        <div class="gd-kicker" title="${_escHtml(typeof _rtGoldKickerTitle === "function" ? _rtGoldKickerTitle() : "")}">${_escHtml(typeof _rtGoldKicker === "function" ? _rtGoldKicker() : "Gold · COMEX futures (GC=F) · delayed")}</div>
        <div class="gd-px">$${_gdPx(px)} <span class="gd-chg ${chgCls}">${chg != null ? _gdChg(chg) : ""}</span></div>
        ${heroSub ? `<div class="gd-sub">${_escHtml(heroSub)}</div>` : ""}
      </div>
      <div class="gd-hero-right">
        ${_gdSpark(g.spark)}
        <div class="gd-macro-mini">
          <span>DXY <b>${dxyTxt}</b></span>
          <span>10Y <b>${d.macro?.tnx?.px != null ? d.macro.tnx.px + "%" : "—"}</b></span>
          <span>VIX <b>${d.macro?.vix?.px != null ? d.macro.vix.px : "—"}</b></span>
        </div>
      </div>
    </div>
    <div class="gd-hero-foot">
      <div class="gd-asof">Spot: reference feed · Levels &amp; volatility: COMEX gold futures (GC=F) daily bars, Yahoo Finance, delayed${gs ? ` · as of ${_escHtml(_fmtAsOf(gs.asOf))}` : ""} · AI scenario analysis${aiAt ? ` ${_escHtml(aiAt)}` : ""}</div>
      <button type="button" class="gd-refresh" onclick="loadGoldDesk(true)"${_goldDeskLoad ? " disabled" : ""}>${_goldDeskLoad ? "Refreshing…" : "↻ Refresh"}</button>
    </div>
  </div>`;

  if (isPlay) {
    const pb = d.playbook || {};
    const sc = pb.scenarios || {};

    // The Ladder leads. Read the map before reading the argument.
    // rt14: when the AI saw no price change (spot reference only), its levels are guesses around spot - not drawn.
    const ladder = aiBlind ? "" : _renderLadder(d);
    if (ladder) {
      h += `<section class="gd-ladder-sec">
        <div class="gd-sec-h">Where price sits</div>
        <div class="gd-scen-pick" role="group" aria-label="Scenario to mark on the ladder">
          ${["bullish", "bearish", "range"].map(k => sc[k]
            ? `<button type="button" class="gd-scen-btn${_goldScenario === k ? " on" : ""}" onclick="setGoldScenario('${k}')">${k[0].toUpperCase() + k.slice(1)}</button>`
            : "").join("")}
        </div>
        ${ladder}
      </section>`;
    }

    h += `<div class="gd-card gc">
      <div class="gd-sec-h">Weekly Playbook · ${_escHtml(pb.weekLabel || d.week?.label || "")}</div>
      <div class="gd-badge-row">
        ${bd("CONDITIONAL", "var(--gd)")}
        ${bd((pb.regime?.bias || "range").toUpperCase(), pb.regime?.bias === "bullish" ? "var(--gn)" : pb.regime?.bias === "bearish" ? "var(--rd)" : "var(--bl)")}
        ${bd(pb.weekId || "", "var(--t3)")}
      </div>
      <p class="gd-body">${_escHtml(_rt20GoldAi(pb.regime?.summary || d.structure?.summary || "", _gdHist) || (_gdHist ? _gdStructText(_gdHist) : ""))}</p>
      <p class="gd-disclaimer">${_escHtml(pb.disclaimer || "")}</p>
    </div>`;

    if (pb.macroContext && pb.macroContext.length) {
      h += `<div class="gd-card gc"><div class="gd-sec-h">Macro context</div><ul class="gd-list">${pb.macroContext.map(x => `<li>${_escHtml(x)}</li>`).join("")}</ul></div>`;
    }

    ["bullish", "bearish", "range"].forEach(key => {
      const s = sc[key];
      if (!s) return;
      const col = key === "bullish" ? "var(--gn)" : key === "bearish" ? "var(--rd)" : "var(--bl)";
      h += `<div class="gd-card gc gd-scenario" style="border-left:3px solid ${col}">
        <div class="gd-sec-h" style="color:${col}">${_escHtml(s.title)}</div>
        <div class="gd-if"><span class="gd-if-k">IF / THEN</span>${_escHtml(s.thesis)}</div>
        <div class="gd-row2">
          <div><div class="gd-lbl">Entry conditions</div><div class="gd-sm">${_escHtml(s.entry)}</div></div>
          <div><div class="gd-lbl">Invalidation</div><div class="gd-sm">${_escHtml(s.invalidation)}</div></div>
        </div>
        <div class="gd-lbl" style="margin-top:10px">Targets</div>
        <div class="gd-levels">${(s.targets || []).map(t => `<span class="gd-chip">$${_gdPx(t)}</span>`).join("")}</div>
      </div>`;
    });

    const kl = pb.keyLevels || {};
    const gl = (kl.gammaLiquidity && kl.gammaLiquidity.length ? kl.gammaLiquidity : d.gamma?.levels || []).slice(0, 8);
    if (gl.length) h += `<div class="gd-card gc">
      <div class="gd-sec-h">Gamma & liquidity zones</div>
      <p class="gd-disclaimer">${_escHtml(d.gamma?.disclaimer || "Proxy levels — not dealer GEX.")}</p>
      <div class="gd-levels">${gl.map(L =>
        `<span class="gd-chip" title="${_escHtml(L.label || "")}">$${_gdPx(L.level)} · ${_escHtml(L.label || L.kind || "")}</span>`
      ).join("")}</div>
    </div>`;

    if (pb.eventsThatChangeThesis && pb.eventsThatChangeThesis.length) {
      h += `<div class="gd-card gc"><div class="gd-sec-h">Events that could change the thesis</div>`;
      pb.eventsThatChangeThesis.forEach(e => {
        h += `<div class="gd-event">
          <div class="gd-event-d">${_escHtml(e.date)} · ${bd(e.impact || "medium", e.impact === "high" ? "var(--rd)" : "var(--gd)")}</div>
          <div class="gd-event-t">${_escHtml(e.event)}</div>
          <div class="gd-sm">${_escHtml(e.ifThen)}</div>
        </div>`;
      });
      h += `</div>`;
    }

    if (pb.checklist && pb.checklist.length) {
      h += `<div class="gd-card gc"><div class="gd-sec-h">Week checklist</div><ul class="gd-list">${pb.checklist.map(x => `<li>${_escHtml(x)}</li>`).join("")}</ul></div>`;
    }
  } else {
    // Dashboard tab — rt14: structure, sessions, levels and volatility are computed from COMEX GC=F daily bars.
    // A card with nothing real to show is left out instead of printing "$—", "$0" or "0 touches".
    const f1 = v => `$${_gdPx(Math.round(v * 10) / 10)}`;
    const dayLbl = t => { try { return new Date(t).toLocaleDateString(undefined, { weekday: "short", day: "numeric", month: "short", timeZone: "America/New_York" }); } catch (_) { return ""; } };
    const futNote = gs ? `COMEX gold futures (GC=F) · Yahoo Finance daily bars, delayed · last ${f1(gs.px)}${livePxN != null ? ` · spot is about $${Math.abs(Math.round(gs.px - livePxN))} ${gs.px >= livePxN ? "below" : "above"} futures` : ""}` : "";
    const aiTxt = !aiBlind ? _rt20GoldAi(d.structure?.summary || "", gs) : "";
    const structTxt = gs ? _gdStructText(gs) : aiTxt;
    let grid1 = "";
    if (structTxt) {
      grid1 += `<div class="gd-card gc">
        <div class="gd-sec-h">Market structure</div>
        <div class="gd-body">${_escHtml(structTxt)}</div>
        <div class="gd-badge-row" style="margin-top:10px">${gs ? bd(`${gs.trend} · 20/50-day`, "var(--gd)") + (gs.chgPct != null ? bd(`session ${gs.chgPct >= 0 ? "+" : ""}${gs.chgPct.toFixed(2)}%`, gs.chgPct >= 0 ? "var(--gn)" : "var(--rd)") : "") + (gs.cond ? bd(`vol ${gs.cond}`, "var(--bl)") : "") : bd(d.structure?.bias || "range", "var(--gd)")}</div>
        ${gs ? `<div class="gd-note">Computed from COMEX futures daily bars (20/50-day averages, ATR 14).</div>` : `<div class="gd-note">AI scenario analysis</div>`}
      </div>`;
    }
    if (gs) {
      grid1 += `<div class="gd-card gc">
        <div class="gd-sec-h">Session highs & lows</div>
        <div class="gd-kv"><span>Session high · ${dayLbl(gs.sessDate)}</span><b>${f1(gs.sessHigh)}</b></div>
        <div class="gd-kv"><span>Session low</span><b>${f1(gs.sessLow)}</b></div>
        <div class="gd-kv"><span>Prior day high · ${dayLbl(gs.prevDate)}</span><b>${f1(gs.prevHigh)}</b></div>
        <div class="gd-kv"><span>Prior day low</span><b>${f1(gs.prevLow)}</b></div>
        <div class="gd-note">${_escHtml(futNote)}</div>
      </div>`;
    } else if (_gdHistLoad) {
      grid1 += `<div class="gd-card gc"><div class="gd-sec-h">Session highs & lows</div><div class="gd-muted">Loading COMEX futures bars…</div></div>`;
    } else if (_gdHistErrAt) {
      grid1 += `<div class="gd-card gc"><div class="gd-sec-h">Levels &amp; volatility</div><div class="gd-muted">Futures data did not load just now. Tap Refresh to try again.</div></div>`;
    }
    if (grid1) h += `<div class="gd-grid">${grid1}</div>`;

    if (gs && (gs.sup.length || gs.res.length)) {
      const lvRows = (arr, tag) => arr.map((s, i) => `<div class="gd-kv"><span>${tag}${i + 1} · ${s.hits} touch${s.hits === 1 ? "" : "es"}</span><b>${f1(s.level)}</b></div>`).join("");
      h += `<div class="gd-grid">
      <div class="gd-card gc">
        <div class="gd-sec-h">Support</div>
        ${lvRows(gs.sup, "S") || '<div class="gd-muted">No swing low below price in the last 90 sessions.</div>'}
      </div>
      <div class="gd-card gc">
        <div class="gd-sec-h">Resistance</div>
        ${lvRows(gs.res, "R") || '<div class="gd-muted">No swing high above price in the last 90 sessions.</div>'}
      </div>
    </div>
    <div class="gd-note" style="margin:-4px 2px 12px">Support/resistance: swing lows/highs on COMEX futures daily bars (last 90 sessions), in futures prices. Touches = sessions that came within 0.3%.</div>`;
    }

    if (d.volumeProfile?.bins?.length) {
      h += `<div class="gd-card gc">
      <div class="gd-sec-h">Volume profile</div>
      <div class="gd-kv"><span>POC</span><b>$${_gdPx(d.volumeProfile?.poc)}</b></div>
      <div class="gd-kv"><span>Value area</span><b>$${_gdPx(d.volumeProfile?.val)} – $${_gdPx(d.volumeProfile?.vah)}</b></div>
      ${_gdVpBars(d.volumeProfile?.bins)}
    </div>`;
    }

    if (gs && gs.atr) {
      h += `<div class="gd-card gc">
      <div class="gd-sec-h">Volatility</div>
      <div class="gd-kv"><span>ATR(14) · daily</span><b>${f1(gs.atr)} (${gs.atrPct.toFixed(1)}%)</b></div>
      <div class="gd-kv"><span>Realised vol · 20 days</span><b>${gs.rv != null ? gs.rv.toFixed(1) + "%" : "—"}</b></div>
      <div class="gd-kv"><span>Condition</span><b>${_escHtml(gs.cond || "—")}</b></div>
      <div class="gd-note">COMEX gold futures daily bars. Condition: ATR under 0.9% of price = low, 0.9–1.8% = normal, above 1.8% = elevated.</div>
    </div>`;
    } else if (aiAtr) {
      h += `<div class="gd-card gc">
      <div class="gd-sec-h">Volatility</div>
      <div class="gd-kv"><span>ATR(14)</span><b>$${_gdPx(aiAtr)}</b></div>
      <div class="gd-kv"><span>Condition</span><b>${_escHtml(d.volatility?.condition || "—")}</b></div>
      <div class="gd-note">AI scenario analysis</div>
    </div>`;
    }

    const dxyLc = typeof liveChg === "function" ? liveChg("DXY") : null;
    const dxyChg = dxyLc != null && dxyLc !== 0 ? dxyLc : (Number.isFinite(d.macro?.dxy?.chg) && d.macro.dxy.chg !== 0 ? d.macro.dxy.chg : null);
    h += `<div class="gd-card gc">
      <div class="gd-sec-h">Dollar & yields</div>
      <div class="gd-kv"><span>DXY</span><b>${dxyTxt}${dxyChg != null ? ` <span class="${dxyChg >= 0 ? "px-up" : "px-dn"}">${_gdChg(dxyChg)}</span>` : ""}</b></div>
      <div class="gd-kv"><span>US 10Y</span><b>${d.macro?.tnx?.px != null ? d.macro.tnx.px + "%" : "—"}</b></div>
      <div class="gd-kv"><span>VIX</span><b>${d.macro?.vix?.px != null ? d.macro.vix.px : "—"}</b></div>
    </div>`;

    if ((d.gamma?.levels || []).length) {
      h += `<div class="gd-card gc">
      <div class="gd-sec-h">Gamma / liquidity proxies</div>
      <p class="gd-disclaimer">${_escHtml(d.gamma?.disclaimer || "")}</p>
      <div class="gd-levels">${d.gamma.levels.map(L =>
        `<span class="gd-chip">$${_gdPx(L.level)} · ${_escHtml(L.label || "")}</span>`
      ).join("")}</div>
    </div>`;
    }

    const _unk = v => { const t = String(v == null ? "" : v).trim().toLowerCase(); return !t || t === "unknown" || t === "n/a" || t === "—" || t === "tbd"; };
    const _evs = (d.events || []).filter(e => e && !_unk(e.event) && !_unk(e.date));
    if (_evs.length) {
      h += `<div class="gd-card gc"><div class="gd-sec-h">Upcoming macro events</div>`;
      _evs.forEach(e => {
        h += `<div class="gd-event">
        <div class="gd-event-d">${_escHtml(e.date)}${_unk(e.impact) ? "" : ` · ${bd(e.impact, e.impact === "high" ? "var(--rd)" : "var(--gd)")}`} ${bd(_unk(e.cat) ? "Macro" : e.cat, "var(--bl)")}</div>
        <div class="gd-event-t">${_escHtml(e.event)}</div>
        ${_unk(e.goldNote) ? "" : `<div class="gd-sm">${_escHtml(e.goldNote)}</div>`}
      </div>`;
      });
      h += `${_evs.some(e => !_unk(e.goldNote)) ? `<div class="gd-note">AI scenario analysis</div>` : ""}</div>`;
    }
  }

  return h;
}

// ═══════════════════════════════════════════════════════════
// PAGE: DASHBOARD
// ═══════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════
// PAGE: HOME — the front door of the desk
// ═══════════════════════════════════════════════════════════
// Orientation, not another dashboard: where the tape stands, what the desk is
// saying today, what your own book is doing, and a way back to wherever you
// were. Everything here is a doorway to a surface that owns the detail.
//
// Nothing on this page invents a number. A symbol that has not come back from
// a feed this session is simply absent — see PRODUCT.md on honest provenance.

// Recent destinations, most recent first. Stored because the desk is a tool
// people return to, and "where was I" should survive a reload.
let _recentNav = _lsJson(localStorage.getItem("td_recent_nav"), []);
function _pushRecentNav(p) {
  if (!p || p === "home" || !Array.isArray(_recentNav)) return;
  _recentNav = [p, ..._recentNav.filter(x => x !== p)].slice(0, 6);
  try { localStorage.setItem("td_recent_nav", JSON.stringify(_recentNav)); } catch (e) {}
}

function _isVisitor() {
  // Before /api/me resolves, prefer the published front door. A signed-in
  // session is swapped back to the dense desk as soon as the server confirms it.
  return !_userTierReady || !_userSignedIn;
}

function _isInitialEditorialPath() {
  return !!_initialEditorialRoute
    && /^\/(?:brief|report|research)\/[a-z0-9-]+\/?$/i.test(location.pathname);
}

function _syncFrontDoorMode(page = pg) {
  const publicRoute = document.documentElement.dataset.publicRoute;
  // data-public-route describes the HTML that booted the tab; it is not live
  // application state. Include the destination page so Home -> Desk cannot
  // leave the terminal hidden by stale front-door CSS.
  const homeActive = page === "home" && publicRoute === "home";
  const editorialActive = page === "research" && _isInitialEditorialPath();
  const active = _isVisitor() && (homeActive || editorialActive);
  document.body.classList.toggle("front-door-mode", active);
  document.body.classList.toggle("public-document-mode", active && editorialActive);
  const home = document.getElementById("homeOv");
  if (home) home.classList.toggle("front-door-overlay", active && homeActive);
}

function _isPublicDocumentVisitor(page = pg) {
  if (!_isVisitor()) return false;
  const publicRoute = document.documentElement.dataset.publicRoute;
  return (page === "home" && publicRoute === "home" && !_initialEditorialRoute)
    || (page === "research" && _isInitialEditorialPath());
}

// ── Front-door price paint ──
// The public door used to repaint only at the very end of _fetchLivePrices,
// i.e. after Twelve Data, every Yahoo chunk, Finnhub fallbacks and the
// serialised CoinGecko queue (behind the 8 boot sparkline calls). On phones
// nothing else repaints it (renderMain() returns early for public visitors),
// so the tiles sat on "no print" for the whole loop. Gold/Dollar are known
// after the first ~0.5s reference call, so _fetchLivePrices now paints them
// per stage. Before the first print, a last-known snapshot from this browser
// (localStorage) fills the tile, always labelled LAST SEEN with its as-of
// time and age; it is never presented as a live value.
const FD_SNAP_KEY = "td_fd_snap_v1";
const FD_SNAP_MAX_AGE_MS = 7 * 24 * 60 * 60 * 1000;
const FD_TICKERS = ["XAU", "DXY"];
let _fdSnap = (() => {
  try {
    const d = JSON.parse(localStorage.getItem(FD_SNAP_KEY) || "null");
    return d && typeof d === "object" ? d : {};
  } catch (e) { return {}; }
})();
function _fdSnapRow(tk) {
  const r = _fdSnap && _fdSnap[tk];
  if (!r || typeof r.p !== "number" || !isFinite(r.p) || r.p <= 0) return null;
  const ts = Number(r.ts);
  if (!Number.isFinite(ts) || ts <= 0 || ts > Date.now() + 60_000) return null;
  if (Date.now() - ts > FD_SNAP_MAX_AGE_MS) return null;
  return { p: r.p, ts, name: String(r.name || "") };
}
function _fdSaveSnap() {
  let changed = false;
  FD_TICKERS.forEach(tk => {
    if (!hasSyncedQuote(tk)) return;
    if ((liveQuoteSrc[tk] || "") === "session-cache") return; // first-hand prints only
    const p = P[tk]?.p;
    const ts = Number(liveQuoteTs[tk]);
    if (typeof p !== "number" || !isFinite(p) || p <= 0 || !(ts > 0)) return;
    _fdSnap[tk] = { p, ts, label: _quoteMeta(tk).label, name: liveQuoteName[tk] || "" };
    changed = true;
  });
  if (changed) { try { localStorage.setItem(FD_SNAP_KEY, JSON.stringify(_fdSnap)); } catch (e) {} }
}
function _fdAge(ts) {
  const s = Math.max(0, Math.round((Date.now() - ts) / 1000));
  if (s < 90) return `${s}s`;
  if (s < 5400) return `${Math.round(s / 60)}m`;
  if (s < 172800) return `${Math.round(s / 3600)}h`;
  return `${Math.round(s / 86400)}d`;
}
function _fdFmtPx(p) {
  return p >= 10000 ? Math.round(p).toLocaleString() : p >= 1 ? p.toFixed(2) : p.toFixed(4);
}
function _frontDoorSnapshotQuote(tk, name, description) {
  const r = _fdSnapRow(tk);
  if (!r || !(Date.now() - r.ts < 24 * 3600e3)) return "";
  let asOf = "—";
  try { asOf = new Date(r.ts).toLocaleString([], { weekday: "short", hour: "2-digit", minute: "2-digit" }); } catch (e) {}
  const src = r.name ? `${r.name} · ` : "";
  return `<div class="front-door-quote front-door-quote--snapshot" data-fd-snapshot="1" style="opacity:.72">
    <div class="front-door-quote-name">${_escHtml(name)} <span>${_escHtml(description)}</span></div>
    <div class="front-door-quote-value">${_escHtml(_fdFmtPx(r.p))}</div>
    <div class="front-door-quote-meta">LAST SEEN · ${_escHtml(src)}as of ${_escHtml(asOf)} (${_escHtml(_fdAge(r.ts))} old) · updating…</div>
  </div>`;
}
function _frontDoorQuotesHtml() {
  return _frontDoorQuote("XAU", "GOLD", "spot proxy") + _frontDoorQuote("DXY", "DOLLAR", "US dollar index");
}
/** Repaint only the Gold/Dollar tiles; safe no-op when the front door is not mounted. */
function _paintFrontDoorQuotes() {
  try { _fdSaveSnap(); } catch (e) {}
  if (pg !== "home") return false;
  const boxes = document.querySelectorAll(".front-door-quotes");
  if (!boxes.length) return false;
  const html = _frontDoorQuotesHtml();
  boxes.forEach(b => { b.innerHTML = html; });
  return true;
}
/** Optional server-inlined reference quotes (same shape as /api/market-reference-quotes). */
function _applyInlineQuoteSnapshot() {
  try {
    const el = document.getElementById("dispatch-quote-snapshot");
    if (!el) return 0;
    const data = JSON.parse(el.textContent || "null");
    if (!data || typeof data !== "object") return 0;
    let hits = 0;
    FD_TICKERS.forEach(tk => {
      const q = data[tk];
      if (!q || liveSymbols.has(tk)) return;
      { const qt = Number(q.ts ?? q.fetchedAt); const qms = qt > 0 && qt < 1e10 ? qt * 1000 : qt; if (!(Date.now() - qms < 24 * 3600e3)) return; }
      if (q.ts == null && q.fetchedAt == null) return; // no provider time -> cannot age it honestly
      if (_applyLiveQuote(tk, { ...q, cached: true }, q.source)) hits++;
    });
    return hits;
  } catch (e) { return 0; }
}

function _frontDoorQuote(tk, name, description) {
  tk = (typeof resolveInternalTicker === "function" && resolveInternalTicker(tk)) || tk;
  const synced = hasSyncedQuote(tk);
  if (!synced) {
    const snapTile = _frontDoorSnapshotQuote(tk, name, description);
    if (snapTile) return snapTile;
  }
  const px = synced ? (P[tk]?.p) : null;
  const meta = _quoteMeta(tk);
  const price = (typeof px === "number" && isFinite(px) && px > 0) ? fp(tk).p : "no print";
  const ch = (synced && typeof liveChg === "function") ? liveChg(tk) : null;
  const change = ch != null ? `${ch >= 0 ? "+" : ""}${Number(ch).toFixed(2)}%` : "";
  const referenceName = tk === "XAU"
    ? (liveQuoteName.XAU || "Spot Gold (proxy)")
    : tk === "DXY"
      ? (liveQuoteName.DXY || "Synthetic Dollar Index (proxy)")
      : meta.label;
  const provenance = meta.status === "unavailable"
    ? `NO SYNC · ${referenceName}`
    : `${meta.label} · ${referenceName}`;
  return `<div class="front-door-quote">
    <div class="front-door-quote-name">${_escHtml(name)} <span>${_escHtml(description)}</span></div>
    <div class="front-door-quote-value">${_escHtml(String(price))}${change ? ` <small class="${ch >= 0 ? "px-up" : "px-dn"}">${change}</small>` : ""}</div>
    <div class="front-door-quote-meta">${_escHtml(provenance)}${meta.asOf ? ` · as of ${_escHtml(_fmtAsOf(meta.asOf))}` : ""}${tk === "XAU" && typeof _rtGoldChecked === "function" ? _escHtml(_rtGoldChecked()) : ""}</div>
    ${tk === "XAU" && typeof _rtPaxgLine === "function" ? _rtPaxgLine() : ""}
  </div>`;
}

function _frontDoorStance(brief) {
  const house = String(brief?.houseView || "").toLowerCase();
  if (house.includes("defensive")) return "If gold loses its structure while the dollar firms, the desk will wait for a new base before acting.";
  if (house.includes("constructive")) return "If gold holds its structure while the dollar stays offered, the desk will look for confirmation before adding risk.";
  if (house.includes("opportunistic")) return "If gold reclaims its range with confirmation, the desk will treat the move as an opportunity—not a forecast.";
  return "Know what matters before gold moves.";
}

