function _homeGreeting() {
  let h = new Date().getHours();
  try { h = Number(new Intl.DateTimeFormat("en-GB", { timeZone: "Europe/London", hour: "2-digit", hour12: false }).format(new Date())) % 24; } catch (e) {}
  if (h >= 5 && h < 12) return "Good morning";
  if (h >= 12 && h < 17) return "Good afternoon";
  return "Good evening";
}

/** Live rows from the user's own book — watchlist first, then portfolio. */
function _homeBookRows() {
  const seen = new Set();
  const out = [];
  const push = (tk) => {
    if (!tk || seen.has(tk)) return;
    seen.add(tk);
    const ch = liveChg(tk);
    out.push({ tk, ch: ch != null ? ch : _rt39Chg(tk), px: hasSyncedQuote(tk) ? fp(tk).p : "…" });
  };
  (getActiveWl().tickers || []).forEach(push);
  (portfolio || []).forEach(p => push(p.tk));
  return out.slice(0, 6);
}

