function renderSig(){
  const re = _computeRegimeEngine();
  let h = _renderPgHdr("Signals", "Conviction-weighted · regime-aligned playbook");
  h += _renderSiteIntelCard("signals");
  h += `<div class="gc" style="padding:12px;border-left:3px solid ${re.col};margin-bottom:10px">
    <div style="font-family:var(--mn);font-size:8px;color:${re.col};letter-spacing:0.15em;margin-bottom:6px">REGIME PLAYBOOK · ${re.label}</div>
    <div style="font-size:11px;color:var(--t2);line-height:1.55;margin-bottom:8px">${re.narrative}</div>
    <div style="display:flex;gap:6px;flex-wrap:wrap">${re.overweight.slice(0,3).map(x => `<span style="font-family:var(--mn);font-size:9px;padding:3px 8px;border-radius:6px;background:var(--gnG);color:var(--gn);border:1px solid rgba(16,185,129,0.2)">+ ${x}</span>`).join("")}${re.underweight.slice(0,2).map(x => `<span style="font-family:var(--mn);font-size:9px;padding:3px 8px;border-radius:6px;background:var(--rdG);color:var(--rd);border:1px solid rgba(239,68,68,0.2)">− ${x}</span>`).join("")}</div>
  </div>`;
  SIGS.forEach(s=>{const bc=s.cat.includes("Bull")||s.cat==="Momentum"||s.cat==="Accumulation"||s.cat==="Contrarian"?"var(--gn)":s.cat.includes("Warning")||s.cat==="Geopolitical"?"var(--rd)":"var(--gd)";
    const evidence=_signalEvidence(s);
    const signalCol=evidence.stale?"var(--rd)":bc;
    const convictionLabel=evidence.conviction==null?"ON HOLD":`${evidence.conviction}%`;
    const linked=A.find(a=>s.a.toUpperCase().includes(a.tk)||s.x.toUpperCase().includes(a.tk));
    h+=`<div class="gc gc-a" style="border-left:3px solid ${signalCol};padding:10px;cursor:pointer" onclick="${linked?`openA('${linked.tk}')`:'void(0)'}"><div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:13px;font-weight:700">${s.a}</span><span style="font-family:var(--mn);font-weight:800;font-size:16px;color:${evidence.stale?"var(--rd)":evidence.conviction>=75?"var(--gn)":"var(--gd)"}">${convictionLabel}</span></div>
       <div style="font-size:10.5px;color:var(--t2);line-height:1.45;margin-top:3px">${s.x}</div>
       <div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px;margin-top:8px;padding:7px;border:1px solid ${evidence.stale?"rgba(239,68,68,0.3)":"var(--gb)"};border-radius:6px;background:var(--b1)">
         <span style="font-family:var(--mn);font-size:8px;color:var(--t3)">SOURCE <strong style="color:var(--t2);font-weight:600">${_escHtml(evidence.source)}</strong></span>
         <span style="font-family:var(--mn);font-size:8px;color:var(--t3)">SYMBOL <strong style="color:var(--t2);font-weight:600">${_escHtml(evidence.tk)}</strong></span>
         <span style="font-family:var(--mn);font-size:8px;color:var(--t3)">PRICE <strong style="color:${evidence.stale?"var(--rd)":"var(--tx)"};font-weight:700">${evidence.price}</strong></span>
         <span style="font-family:var(--mn);font-size:8px;color:var(--t3)">AS OF <strong style="color:var(--t2);font-weight:600">${_escHtml(evidence.asOf)}</strong></span>
       </div>
       <div style="display:flex;gap:3px;margin-top:5px;flex-wrap:wrap">${bd(evidence.status,signalCol)}${evidence.reason?bd(evidence.reason,"var(--rd)"):""}${bd(s.cat,bc)}${bd(s.s,s.s==="Strong"?"var(--gn)":"var(--gd)")}${bd(s.tg,"var(--bl)")}${bd(s.hz,"var(--pu)")}${linked?bd(linked.tk,"var(--bl)"):""}</div></div>`;});
  return h;
}

